<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useI18n} from 'vue-i18n'
import Shell from '../components/Shell.vue'
import Chart from '../components/Chart.vue'
import TaskDataMatrix from '../components/TaskDataMatrix.vue'
import {api,errorMessage} from '../api'
import {localizeData} from '../i18n'
import type {DataSource,DatasetProduct,ObservedPilot,MeasurementCoverage} from '../types'
const coverageRaw=ref<MeasurementCoverage>();
const {t,locale}=useI18n();const sourcesRaw=ref<DataSource[]>([]);const productsRaw=ref<DatasetProduct[]>([]);const observedRaw=ref<ObservedPilot|null>(null);const error=ref('');const loading=ref(true);const filter=ref('all');const productFilter=ref('all');const weatherParameter=ref('T2M')
const sources=computed(()=>localizeData(sourcesRaw.value,locale.value));const products=computed(()=>localizeData(productsRaw.value,locale.value));const observed=computed(()=>localizeData(observedRaw.value,locale.value))
const coverage=computed(()=>localizeData(coverageRaw.value,locale.value))
const filtered=computed(()=>sources.value.filter(s=>filter.value==='all'||(filter.value==='official')===s.official))
const filteredProducts=computed(()=>products.value.filter(p=>productFilter.value==='all'||p.status===productFilter.value))
const windows=computed(()=>observed.value?[observed.value.target,...observed.value.candidates]:[])
const palette=['#91bfe1','#91ddba','#e3c487','#c5a9ec']
const chartBase={textStyle:{color:'#b3c0ce'},tooltip:{trigger:'axis' as const},legend:{textStyle:{color:'#b3c0ce'},type:'scroll' as const},grid:{left:65,right:25,top:65,bottom:55}}
const terrainOption=computed(()=>({...chartBase,xAxis:{type:'value' as const,name:t('slopeDegrees'),nameLocation:'middle' as const,nameGap:30},yAxis:{type:'value' as const,min:0,max:1,name:t('ecdf'),splitLine:{lineStyle:{color:'#26313d'}}},series:windows.value.map((site,index)=>({name:site.name,type:'line' as const,step:'end' as const,showSymbol:false,color:palette[index],data:[...site.slope_samples_deg].sort((a,b)=>a-b).map((x,i,array)=>[x,(i+1)/array.length])}))}))
const weatherKeys=['T2M','WS10M','ALLSKY_SFC_SW_DWN'] as const
const weatherLabels={T2M:'airTemperature',WS10M:'windSpeed',ALLSKY_SFC_SW_DWN:'shortwave'}
const weatherOption=computed(()=>({...chartBase,xAxis:{type:'value' as const,name:t('localHour'),nameLocation:'middle' as const,nameGap:30,min:0,max:23},yAxis:{type:'value' as const,name:observed.value?.meteorology[0]?.parameters[weatherParameter.value]?.units,splitLine:{lineStyle:{color:'#26313d'}}},series:observed.value?.meteorology.map((site,index)=>({name:site.name,type:'line' as const,showSymbol:false,color:palette[index+1],data:site.parameters[weatherParameter.value]?.mean_cycle.map((y,h)=>[h,y])}))}))
async function load(){error.value='';loading.value=true;try{[sourcesRaw.value,productsRaw.value,observedRaw.value,coverageRaw.value]=await Promise.all([api.sources(),api.datasets(),api.observations(),api.coverage()])}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
onMounted(load)
</script>
<template><Shell><div class="page-head"><span class="eyebrow">{{t('evidenceLibrary')}}</span><h1>{{t('data')}}</h1><p>{{t('dataIntro')}}</p><router-link to="/research">{{t('researchLink')}} ↗</router-link></div><div v-if="error" class="error-panel" role="alert">{{error}} <button @click="load">{{t('retry')}}</button></div><p v-if="loading" class="loading-state">{{t('loading')}}…</p>
<TaskDataMatrix v-if="coverage" :coverage="coverage"/><section id="observed" class="section observed-section"><div class="section-heading"><div><span class="eyebrow">{{t('observedBadge')}}</span><h2>{{t('observedPilot')}}</h2></div><p class="muted">{{t('observedIntro')}}</p></div><template v-if="observed"><p class="notice">{{observed.scope}}</p><p class="small muted">{{t('createdAt')}}: {{new Date(observed.created_at).toLocaleString(locale==='en'?'en-US':'zh-TW')}}</p><div class="table-scroll"><table><thead><tr><th>{{t('window')}}</th><th>{{t('meanSlope')}}</th><th>{{t('p90Slope')}}</th><th>{{t('relief')}}</th><th>{{t('validPixels')}}</th></tr></thead><tbody><tr v-for="site in windows" :key="site.id"><th><a :href="site.source_url" target="_blank" rel="noopener">{{site.name}} ↗</a><small class="coordinate-caption">{{site.lat.toFixed(5)}}°, {{site.lon.toFixed(5)}}°</small></th><td>{{site.statistics.mean_slope_deg.toFixed(2)}}</td><td>{{site.statistics.p90_slope_deg.toFixed(2)}}</td><td>{{site.statistics.relief_p95_p05_m.toFixed(2)}}</td><td>{{site.statistics.sample_count}} / {{(site.statistics.valid_fraction*100).toFixed(0)}}%</td></tr></tbody></table></div><article class="panel"><h3>{{t('terrainDistribution')}}</h3><Chart :option="terrainOption" :label="t('terrainDistribution')"/></article><ul class="evidence-caveats"><li v-for="caveat in observed.caveats" :key="caveat">{{caveat}}</li></ul>
<article v-if="observed.meteorology.length" class="panel"><h3>{{t('weatherContext')}}</h3><p class="small muted">{{t('weatherIntro')}}</p><label>{{t('choose')}} <select v-model="weatherParameter"><option v-for="key in weatherKeys" :key="key" :value="key">{{t(weatherLabels[key])}}</option></select></label><Chart :option="weatherOption" :label="t('weatherContext')"/></article>
<details class="provenance-details"><summary>{{t('provenance')}} ({{observed.downloads.length}})</summary><ul><li v-for="file in observed.downloads" :key="file.sha256"><a :href="file.url" target="_blank" rel="noopener">{{t('source')}} ↗</a> · {{t('downloadSize')}}: {{(file.bytes/1024/1024).toFixed(2)}} MiB <small>{{t('retrievedAt')}}: {{file.retrieved_at}}</small><code>SHA-256: {{file.sha256}}</code></li></ul></details></template><p v-else-if="!loading" class="notice">{{t('observedMissing')}}</p></section>
<section class="section"><div class="section-heading"><h2>{{t('products')}}</h2><select v-model="productFilter" :aria-label="t('status')"><option value="all">{{t('allProducts')}}</option><option v-for="status in ['imported','planned','account_required','reference']" :key="status" :value="status">{{t('status_'+status)}}</option></select></div><div class="product-grid"><article v-for="product in filteredProducts" :key="product.id" class="source-card"><span class="badge" :class="product.status==='imported'?'official':'supplement'">{{t('status_'+product.status)}}</span><h3><a :href="product.url" target="_blank" rel="noopener">{{product.name}} ↗</a></h3><dl><dt>{{t('productResolution')}}</dt><dd>{{product.resolution}}</dd><dt>{{t('access')}}</dt><dd>{{t('access_'+product.access)}}</dd></dl><div class="feature-tags"><span v-for="id in product.uses" :key="id">{{id}}</span></div><p v-for="note in product.notes" :key="note" class="small muted">{{note}}</p></article></div></section>
<section class="section data-section"><h2>{{t('source')}}</h2><div class="filter-row"><button v-for="key in ['all','official','supplement']" :key="key" :class="{active:filter===key}" @click="filter=key">{{t(key==='all'?'filterAll':key)}} <span>{{key==='all'?sources.length:sources.filter(s=>(key==='official')===s.official).length}}</span></button></div><div class="source-grid"><article v-for="source in filtered" :key="source.id" class="source-card"><span class="badge" :class="source.official?'official':'supplement'">{{source.official?'✓':'+'}} {{t(source.official?'official':'supplement')}}</span><h3>{{source.name}}</h3><a v-if="source.url" :href="source.url" target="_blank" rel="noopener">{{t('source')}} ↗</a><span v-else class="warning">{{t('todo')}}</span><h4>{{t('usedBy')}}</h4><div v-if="source.used_by.length" class="feature-tags"><span v-for="id in source.used_by" :key="id">{{id}}</span></div><p v-else class="small muted">{{t('notUsed')}}</p><p class="small muted">{{source.notes}}</p></article></div></section></Shell></template>
